vector<int> nextGreater(vector<int>& a) {
    int n = a.size();
    vector<int> ans(n, -1);
    stack<int> st;                 // indices, values decreasing
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && a[st.top()] < a[i]) {
            ans[st.top()] = a[i];
            st.pop();
        }
        st.push(i);
    }
    return ans;
}

def next_greater(a):
    n = len(a)
    ans = [-1] * n
    st = []                    # indices, values decreasing
    for i in range(n):
        while st and a[st[-1]] < a[i]:
            ans[st.pop()] = a[i]
        st.append(i)
    return ans

class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& q, vector<int>& nums) {
        unordered_map<int,int> nge; stack<int> st;
        for (int x : nums) {
            while (!st.empty() && st.top() < x) { nge[st.top()] = x; st.pop(); }
            st.push(x);
        }
        vector<int> res;
        for (int x : q) res.push_back(nge.count(x) ? nge[x] : -1);
        return res;
    }
};

class Solution:
    def nextGreaterElement(self, q: list[int], nums: list[int]) -> list[int]:
        nge, st = {}, []
        for x in nums:
            while st and st[-1] < x:
                nge[st.pop()] = x
            st.append(x)
        return [nge.get(x, -1) for x in q]

class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& t) {
        int n = t.size(); vector<int> res(n, 0); stack<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && t[st.top()] < t[i]) { res[st.top()] = i - st.top(); st.pop(); }
            st.push(i);
        }
        return res;
    }
};

class Solution:
    def dailyTemperatures(self, t: list[int]) -> list[int]:
        res, st = [0] * len(t), []
        for i, temp in enumerate(t):
            while st and t[st[-1]] < temp:
                j = st.pop()
                res[j] = i - j
            st.append(i)
        return res

class Solution {
public:
    int largestRectangleArea(vector<int>& h) {
        h.push_back(0); stack<int> st; int best = 0;
        for (int i = 0; i < (int)h.size(); i++) {
            while (!st.empty() && h[st.top()] > h[i]) {
                int height = h[st.top()]; st.pop();
                int width = st.empty() ? i : i - st.top() - 1;
                best = max(best, height * width);
            }
            st.push(i);
        }
        return best;
    }
};

class Solution:
    def largestRectangleArea(self, h: list[int]) -> int:
        h = h + [0]
        st, best = [], 0
        for i, height in enumerate(h):
            while st and h[st[-1]] > height:
                top = st.pop()
                width = i if not st else i - st[-1] - 1
                best = max(best, h[top] * width)
            st.append(i)
        return best

class Solution {
public:
    int trap(vector<int>& h) {
        stack<int> st; int water = 0;
        for (int i = 0; i < (int)h.size(); i++) {
            while (!st.empty() && h[i] > h[st.top()]) {
                int bottom = st.top(); st.pop();
                if (st.empty()) break;
                int width = i - st.top() - 1;
                int bounded = min(h[i], h[st.top()]) - h[bottom];
                water += width * bounded;
            }
            st.push(i);
        }
        return water;
    }
};

class Solution:
    def trap(self, h: list[int]) -> int:
        st, water = [], 0
        for i, x in enumerate(h):
            while st and x > h[st[-1]]:
                bottom = st.pop()
                if not st:
                    break
                width = i - st[-1] - 1
                bounded = min(x, h[st[-1]]) - h[bottom]
                water += width * bounded
            st.append(i)
        return water

class Solution {
public:
    string removeKdigits(string num, int k) {
        string st;
        for (char c : num) {
            while (!st.empty() && k > 0 && st.back() > c) { st.pop_back(); k--; }
            st.push_back(c);
        }
        st.resize(st.size() - k);
        int i = 0; while (i < (int)st.size() && st[i] == '0') i++;
        string res = st.substr(i);
        return res.empty() ? "0" : res;
    }
};

class Solution:
    def removeKdigits(self, num: str, k: int) -> str:
        st = []
        for c in num:
            while st and k > 0 and st[-1] > c:
                st.pop(); k -= 1
            st.append(c)
        st = st[:len(st) - k] if k else st
        res = ''.join(st).lstrip('0')
        return res or '0'
